import assert from 'node:assert/strict';
import {createNativeSlideBody} from './native-slide-body.mjs';
const frame={ticks:2,obsel:3,tiles:[],parts:[],cgram:Buffer.alloc(512).toString('base64')};
const data={schema:'issd-slide-lab-local/v1',width:96,height:96,frames:Array.from({length:6},()=>({...frame}))};
const locomotion={schema:'issd-runtime-body-local/v1',cycles:{walking:Array.from({length:8},()=>({height:52}))}};
const preview={schema:'issd-editor-preview-local/v1',teams:Array.from({length:36},()=>({palettes:[Array(16).fill(0),Array(16).fill(1)]}))};
const make=(w,h)=>({width:w,height:h,getContext:()=>({createImageData:()=>({data:new Uint8ClampedArray(w*h*4)}),putImageData(){}})});
const slide=createNativeSlideBody(data,locomotion,make,preview),req={team:30,kit:'home',appearance:{skin_tone:0,hair_style:3},position:'DF',screenDirection:2,palette:Array(16).fill('#000000')};
const both=createNativeSlideBody(data,locomotion,make,preview,data);
assert.equal(both.supports({...req,screenDirection:6}),true);
assert.notEqual(both.frame(0,req),both.frame(0,{...req,screenDirection:6}),'direction is part of cache key');
assert.equal(slide.supports({...req,screenDirection:6}),false);
assert.throws(()=>createNativeSlideBody(data,locomotion,make,preview,{...data,frames:[frame]}));
assert.equal(slide.duration,12);assert.equal(slide.referenceHeight(2),52);assert.equal(slide.supports(req),true);
for(const team of [0,2,30,35])for(const kit of ['home','away'])for(const skin of [0,1])assert.equal(slide.supports({...req,team,kit,appearance:{skin_tone:skin,hair_style:3}}),true);
for(const o of [{team:36},{kit:'invalid'},{appearance:{skin_tone:2,hair_style:0}},{screenDirection:3},{position:'GK'},{palette:[]}])assert.equal(slide.supports({...req,...o}),false);
assert.equal(slide.frame(-1,req),null);assert.equal(slide.frame(12,req),null);assert.equal(slide.frame(0,req),slide.frame(1,req));assert.notEqual(slide.frame(1,req),slide.frame(2,req));
assert.notEqual(slide.frame(0,req),slide.frame(0,{...req,team:2}),'cache separates teams');
assert.throws(()=>createNativeSlideBody({...data,frames:[frame]},locomotion,make,preview));

const detailFrame={...frame,parts:[{slot:0,x:0,y:0,tile:0,attr:8,size:8}],detail_address:0,detail_variants:Array(720).fill(0)};
const directional={schema:'issd-slide-directions-local/v1',width:96,height:96,cycles:{0:Array.from({length:6},()=>({...detailFrame}))},detail_pool:[Buffer.alloc(32).toString('base64')]};
const manifest={schema:'issd-team-detail-colors/v1',teams:Array.from({length:36},(_,team_id)=>({team_id,home:{selector:1,bgr555:512},away:{selector:0,bgr555:null}}))};
const dynamic=createNativeSlideBody(data,locomotion,make,preview,null,directional,manifest);
const detailReq={...req,screenDirection:0,shirtNumber:7};
assert.equal(dynamic.supports(detailReq),true);
assert.ok(dynamic.frame(0,detailReq));
assert.equal(dynamic.supports({...detailReq,kit:'away'}),false,'no-write palette is not guessed');
assert.equal(dynamic.supports({...detailReq,shirtNumber:21}),false);
const missing={...directional,cycles:{0:directional.cycles[0].map(f=>({...f,detail_variants:Array(720).fill(null)}))}};
assert.equal(createNativeSlideBody(data,locomotion,make,preview,null,missing,manifest).supports(detailReq),false,'unverified detail cannot render');

console.log('OK: carrinho visual por equipe e uniforme, limitado à direção capturada');
